CREATE TABLE competition_stages (id UUID PRIMARY KEY,competition_id UUID NOT NULL REFERENCES competitions(id),name VARCHAR(80) NOT NULL,stage_type VARCHAR(20) NOT NULL,stage_order INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE competition_groups (id UUID PRIMARY KEY,stage_id UUID NOT NULL REFERENCES competition_stages(id),name VARCHAR(40) NOT NULL,group_order INTEGER NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE competition_group_members (id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES competition_groups(id),user_id UUID NOT NULL REFERENCES users(id),position INTEGER,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(group_id,user_id));
CREATE TABLE matches (id UUID PRIMARY KEY,competition_id UUID NOT NULL REFERENCES competitions(id),stage_id UUID NOT NULL REFERENCES competition_stages(id),group_id UUID,round_number INTEGER,match_number INTEGER NOT NULL,table_number VARCHAR(30),scheduled_at TIMESTAMPTZ,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,status VARCHAR(20) NOT NULL,best_of INTEGER NOT NULL,player_a_user_id UUID,player_b_user_id UUID,player_a_games INTEGER NOT NULL DEFAULT 0,player_b_games INTEGER NOT NULL DEFAULT 0,winner_user_id UUID,loser_user_id UUID,result_type VARCHAR(20),rating_eligible BOOLEAN NOT NULL DEFAULT FALSE,result_reason VARCHAR(500),next_match_id UUID,winner_to_slot VARCHAR(1),version BIGINT NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_matches_competition_status ON matches(competition_id,status);CREATE INDEX idx_matches_stage_round_number ON matches(stage_id,round_number,match_number);CREATE INDEX idx_matches_a ON matches(player_a_user_id);CREATE INDEX idx_matches_b ON matches(player_b_user_id);
CREATE TABLE match_games (id UUID PRIMARY KEY,match_id UUID NOT NULL REFERENCES matches(id),game_number INTEGER NOT NULL,player_a_score INTEGER NOT NULL,player_b_score INTEGER NOT NULL,winner_user_id UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(match_id,game_number));
CREATE TABLE rating_settlements (id UUID PRIMARY KEY,competition_id UUID NOT NULL UNIQUE REFERENCES competitions(id),rule_version VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,completed_at TIMESTAMPTZ);
CREATE UNIQUE INDEX uq_rating_ledger_match_user ON rating_ledger(match_id,user_id) WHERE source_type='MATCH';
